import { Router } from "express";
import { z } from "zod";
import { prisma } from "../../lib/prisma.js";
import { authenticate } from "../auth/auth.middleware.js";
import { withTenantContext, withPlatformContext } from "../auth/tenant-context.js";
import { hasSchoolPermission } from "../auth/school-permissions.js";
import { hasSchoolAdminAccess } from "../organizations/organization.authorization.js";
import { hasActiveSchoolMembership } from "../schools/school-config.authorization.js";
export const canteenRouter=Router(); canteenRouter.use(authenticate);
const wrap=(fn:(req:any,res:any)=>Promise<any>)=>(req:any,res:any,next:any)=>Promise.resolve(fn(req,res)).catch(next);
async function scope(req:any,res:any,permission="canteen.read"){const organizationId=String(req.params.organizationId||""),schoolId=String(req.params.schoolId||""),userId=req.auth!.userId;if(!await hasActiveSchoolMembership(userId,organizationId,schoolId)){res.status(403).json({error:"Active school membership required"});return null;}if(!await hasSchoolAdminAccess(userId,organizationId,schoolId)&&!await hasSchoolPermission(userId,organizationId,schoolId,permission)){res.status(403).json({error:`Missing required permission: ${permission}`});return null;}return {organizationId,schoolId,userId};}
const base="/:organizationId/:schoolId/canteen";
async function parentCanteenStudentIds(userId:string,organizationId:string,schoolId:string){return withTenantContext(prisma,{userId,organizationId,schoolId},async tx=>{const [membership,orgMembership,role]=await Promise.all([tx.schoolMembership.findFirst({where:{userId,organizationId,schoolId,status:"ACTIVE"},select:{id:true}}),tx.organizationMembership.findFirst({where:{userId,organizationId,status:"ACTIVE"},select:{id:true}}),tx.userRoleAssignment.findFirst({where:{userId,organizationId,schoolId,scopeType:"SCHOOL",role:{key:"PARENT",rolePermissions:{some:{permission:{key:"parent.canteen.read"}}}}},select:{id:true}})]);if(!membership||!orgMembership||!role)return [];const guardians=await tx.guardian.findMany({where:{organizationId,schoolId,userId,isActive:true,emailVerifiedAt:{not:null}},select:{id:true}});if(!guardians.length)return [];const accepted=await tx.parentInvitation.findMany({where:{organizationId,schoolId,guardianId:{in:guardians.map(g=>g.id)},status:"ACCEPTED",consentAcceptedAt:{not:null},consentWithdrawnAt:null},select:{guardianId:true}});const guardianIds=[...new Set(accepted.map(g=>g.guardianId))];if(!guardianIds.length)return [];const links=await tx.studentGuardian.findMany({where:{organizationId,schoolId,guardianId:{in:guardianIds},canReceiveCommunications:true},select:{studentId:true}});return [...new Set(links.map(l=>l.studentId))];});}

const itemSchema=z.object({name:z.string().trim().min(1).max(120),description:z.string().max(1000).optional(),category:z.string().trim().min(1).max(50).optional(),price:z.number().nonnegative().max(100000),dietaryTags:z.array(z.string().trim().max(30)).max(20).optional(),allergens:z.array(z.string().trim().min(1).max(50)).max(30).optional(),availableOn:z.string().datetime().nullable().optional(),isAvailable:z.boolean().optional()});
// P551: allergen safety profile checks are tenant/school scoped and fail closed when profile allergens intersect menu items.
async function canteenAllergenCheck(tx:any,organizationId:string,schoolId:string,studentId:string,menuItems:any[]){
 const profile=await tx.canteenStudentDietarySafety.findFirst({where:{organizationId,schoolId,studentId}});
 const restricted=(profile?.allergens||[]).map((x:string)=>x.trim().toLowerCase()).filter(Boolean);
 const conflicts=menuItems.flatMap((item:any)=>{const declared=(item.allergens||[]).filter((a:string)=>a.trim());const hits=declared.filter((a:string)=>restricted.includes(a.trim().toLowerCase()));if(hits.length)return [{menuItemId:item.id,itemName:item.name,allergens:hits}];if(restricted.length&&!declared.length)return [{menuItemId:item.id,itemName:item.name,allergens:[],reason:"ALLERGEN_LABELS_MISSING"}];return [];});
 return {profile,conflicts};
}

canteenRouter.get(base+"/dashboard",wrap(async(req,res)=>{const s=await scope(req,res);if(!s)return;const today=new Date();today.setHours(0,0,0,0);const tomorrow=new Date(today);tomorrow.setDate(tomorrow.getDate()+1);const [items,orders,stockRows]=await withTenantContext(prisma,s,tx=>Promise.all([tx.canteenMenuItem.count({where:{organizationId:s.organizationId,schoolId:s.schoolId,isAvailable:true}}),tx.canteenOrder.count({where:{organizationId:s.organizationId,schoolId:s.schoolId,orderDate:{gte:today,lt:tomorrow}}}),tx.canteenStockItem.findMany({where:{organizationId:s.organizationId,schoolId:s.schoolId},select:{quantity:true,reorderLevel:true}})]));const stock=stockRows.length;const lowStock=stockRows.filter(row=>Number(row.quantity)<=Number(row.reorderLevel)).length;return res.json({data:{activeMenuItems:items,todayOrders:orders,stockItems:stock,lowStock}});}));

// P551 dietary safety profiles: limited structured fields; manage access is school-scoped.
canteenRouter.get(base+"/dietary-safety/profiles",wrap(async(req,res)=>{const s=await scope(req,res,"canteen.manage");if(!s)return;const data=await withTenantContext(prisma,s,tx=>tx.canteenStudentDietarySafety.findMany({where:{organizationId:s.organizationId,schoolId:s.schoolId},orderBy:{updatedAt:"desc"},take:500}));return res.json({data});}));
canteenRouter.put(base+"/dietary-safety/profiles/:studentId",wrap(async(req,res)=>{const s=await scope(req,res,"canteen.manage");if(!s)return;const p=z.object({allergens:z.array(z.string().trim().min(1).max(50)).max(30),dietaryRestrictions:z.array(z.string().trim().min(1).max(80)).max(30).default([]),notes:z.string().max(300).optional()}).safeParse(req.body);if(!p.success)return res.status(400).json({error:"Invalid dietary safety profile",details:p.error.flatten()});const data=await withTenantContext(prisma,s,async tx=>{const student=await tx.student.findFirst({where:{id:req.params.studentId,organizationId:s.organizationId,schoolId:s.schoolId,status:"ACTIVE"},select:{id:true}});if(!student)throw Object.assign(new Error("Active student not found"),{status:404});return tx.canteenStudentDietarySafety.upsert({where:{organizationId_schoolId_studentId:{organizationId:s.organizationId,schoolId:s.schoolId,studentId:student.id}},create:{organizationId:s.organizationId,schoolId:s.schoolId,studentId:student.id,...p.data,createdBy:s.userId,reviewedAt:new Date(),reviewedBy:s.userId},update:{...p.data,reviewedAt:new Date(),reviewedBy:s.userId}});});return res.json({data});}));
canteenRouter.get(base+"/dietary-safety/analytics",wrap(async(req,res)=>{const s=await scope(req,res);if(!s)return;const data=await withTenantContext(prisma,s,async tx=>{const [profiles,menu,orders]=await Promise.all([tx.canteenStudentDietarySafety.count({where:{organizationId:s.organizationId,schoolId:s.schoolId}}),tx.canteenMenuItem.findMany({where:{organizationId:s.organizationId,schoolId:s.schoolId,isAvailable:true},select:{id:true,name:true,allergens:true,dietaryTags:true}}),tx.canteenOrder.count({where:{organizationId:s.organizationId,schoolId:s.schoolId}})]);const allergenCounts:Record<string,number>={};for(const item of menu)for(const allergen of item.allergens||[])allergenCounts[allergen]=(allergenCounts[allergen]||0)+1;return {profileCount:profiles,activeMenuCount:menu.length,orderCount:orders,menuItemsMissingAllergenLabels:menu.filter(i=>(i.allergens||[]).length===0).map(i=>({id:i.id,name:i.name})),allergenMenuCounts:allergenCounts,dietaryTaggedMenuCount:menu.filter(i=>(i.dietaryTags||[]).length>0).length};});return res.json({data});}));
canteenRouter.get(base+"/menu",wrap(async(req,res)=>{const s=await scope(req,res);if(!s)return;const data=await withTenantContext(prisma,s,tx=>tx.canteenMenuItem.findMany({where:{organizationId:s.organizationId,schoolId:s.schoolId},orderBy:[{category:"asc"},{name:"asc"}],take:500}));return res.json({data});}));
canteenRouter.post(base+"/menu",wrap(async(req,res)=>{const s=await scope(req,res,"canteen.manage");if(!s)return;const p=itemSchema.safeParse(req.body);if(!p.success)return res.status(400).json({error:"Invalid menu item",details:p.error.flatten()});const data=await withTenantContext(prisma,s,tx=>tx.canteenMenuItem.create({data:{organizationId:s.organizationId,schoolId:s.schoolId,createdBy:s.userId,...p.data,price:p.data.price,availableOn:p.data.availableOn?new Date(p.data.availableOn):null}}));return res.status(201).json({data});}));
canteenRouter.patch(base+"/menu/:itemId",wrap(async(req,res)=>{const s=await scope(req,res,"canteen.manage");if(!s)return;const p=itemSchema.partial().safeParse(req.body);if(!p.success)return res.status(400).json({error:"Invalid menu item",details:p.error.flatten()});const data=await withTenantContext(prisma,s,async tx=>{const existing=await tx.canteenMenuItem.findFirst({where:{id:req.params.itemId,organizationId:s.organizationId,schoolId:s.schoolId}});if(!existing)return null;return tx.canteenMenuItem.update({where:{id:existing.id},data:{...p.data,availableOn:p.data.availableOn?new Date(p.data.availableOn):undefined}});});if(!data)return res.status(404).json({error:"Menu item not found"});return res.json({data});}));
canteenRouter.get(base+"/meal-plans",wrap(async(req,res)=>{const s=await scope(req,res);if(!s)return;const data=await withTenantContext(prisma,s,tx=>tx.canteenMealPlan.findMany({where:{organizationId:s.organizationId,schoolId:s.schoolId},orderBy:{createdAt:"desc"}}));return res.json({data});}));
canteenRouter.post(base+"/meal-plans",wrap(async(req,res)=>{const s=await scope(req,res,"canteen.manage");if(!s)return;const p=z.object({name:z.string().trim().min(1).max(100),description:z.string().max(500).optional(),price:z.number().nonnegative(),startDate:z.string().datetime().nullable().optional(),endDate:z.string().datetime().nullable().optional()}).safeParse(req.body);if(!p.success)return res.status(400).json({error:"Invalid meal plan"});const data=await withTenantContext(prisma,s,tx=>tx.canteenMealPlan.create({data:{organizationId:s.organizationId,schoolId:s.schoolId,createdBy:s.userId,name:p.data.name,description:p.data.description,price:p.data.price,startDate:p.data.startDate?new Date(p.data.startDate):null,endDate:p.data.endDate?new Date(p.data.endDate):null}}));return res.status(201).json({data});}));
canteenRouter.get(base+"/allocations",wrap(async(req,res)=>{const s=await scope(req,res);if(!s)return;const data=await withTenantContext(prisma,s,tx=>tx.canteenMealAllocation.findMany({where:{organizationId:s.organizationId,schoolId:s.schoolId},orderBy:{createdAt:"desc"},take:200}));return res.json({data});}));
canteenRouter.post(base+"/allocations",wrap(async(req,res)=>{const s=await scope(req,res,"canteen.manage");if(!s)return;const p=z.object({studentId:z.string().min(1),mealPlanId:z.string().optional(),validFrom:z.string().datetime(),validTo:z.string().datetime().nullable().optional()}).safeParse(req.body);if(!p.success)return res.status(400).json({error:"Invalid allocation"});const data=await withTenantContext(prisma,s,async tx=>{const student=await tx.student.findFirst({where:{id:p.data.studentId,organizationId:s.organizationId,schoolId:s.schoolId,status:"ACTIVE"},select:{id:true}});if(!student)throw Object.assign(new Error("Active student not found"),{status:404});if(p.data.mealPlanId&&!await tx.canteenMealPlan.findFirst({where:{id:p.data.mealPlanId,organizationId:s.organizationId,schoolId:s.schoolId}}))throw Object.assign(new Error("Meal plan not found"),{status:404});return tx.canteenMealAllocation.create({data:{organizationId:s.organizationId,schoolId:s.schoolId,studentId:student.id,mealPlanId:p.data.mealPlanId,validFrom:new Date(p.data.validFrom),validTo:p.data.validTo?new Date(p.data.validTo):null,createdBy:s.userId}});});return res.status(201).json({data});}));
canteenRouter.get(base+"/orders",wrap(async(req,res)=>{const s=await scope(req,res);if(!s)return;const data=await withTenantContext(prisma,s,tx=>tx.canteenOrder.findMany({where:{organizationId:s.organizationId,schoolId:s.schoolId},include:{items:true},orderBy:{createdAt:"desc"},take:200}));return res.json({data});}));
canteenRouter.post(base+"/orders",wrap(async(req,res)=>{const s=await scope(req,res,"canteen.manage");if(!s)return;const p=z.object({studentId:z.string().min(1),orderDate:z.string().datetime(),notes:z.string().max(500).optional(),items:z.array(z.object({menuItemId:z.string().min(1),quantity:z.number().int().min(1).max(100)})).min(1).max(30)}).safeParse(req.body);if(!p.success)return res.status(400).json({error:"Invalid order",details:p.error.flatten()});const data=await withTenantContext(prisma,s,async tx=>{const student=await tx.student.findFirst({where:{id:p.data.studentId,organizationId:s.organizationId,schoolId:s.schoolId,status:"ACTIVE"},select:{id:true}});if(!student)throw Object.assign(new Error("Active student not found"),{status:404});const menu=await tx.canteenMenuItem.findMany({where:{id:{in:p.data.items.map(i=>i.menuItemId)},organizationId:s.organizationId,schoolId:s.schoolId,isAvailable:true}});if(menu.length!==new Set(p.data.items.map(i=>i.menuItemId)).size)throw Object.assign(new Error("One or more menu items are unavailable"),{status:400});const safety=await canteenAllergenCheck(tx,s.organizationId,s.schoolId,student.id,menu);if(safety.conflicts.length)throw Object.assign(new Error("Order blocked by dietary/allergen safety profile"),{status:409,details:safety.conflicts});const orderItems=p.data.items.map(i=>{const item=menu.find(m=>m.id===i.menuItemId)!;const unit=Number(item.price);return {menuItemId:item.id,itemName:item.name,quantity:i.quantity,unitPrice:unit,lineTotal:unit*i.quantity};});const total=orderItems.reduce((sum,i)=>sum+i.lineTotal,0);return tx.canteenOrder.create({data:{organizationId:s.organizationId,schoolId:s.schoolId,studentId:student.id,orderDate:new Date(p.data.orderDate),notes:p.data.notes,createdBy:s.userId,total,items:{create:orderItems}},include:{items:true}});});return res.status(201).json({data});}));
canteenRouter.patch(base+"/orders/:orderId/status",wrap(async(req,res)=>{const s=await scope(req,res,"canteen.serve");if(!s)return;const p=z.object({status:z.enum(["PLACED","PREPARING","READY","CANCELLED"])}).safeParse(req.body);if(!p.success)return res.status(400).json({error:"Invalid order status"});const data=await withTenantContext(prisma,s,async tx=>{const order=await tx.canteenOrder.findFirst({where:{id:req.params.orderId,organizationId:s.organizationId,schoolId:s.schoolId}});if(!order)return null;if(order.status==="SERVED"||order.status==="CANCELLED")throw Object.assign(new Error("Completed orders cannot be changed"),{status:409});return tx.canteenOrder.update({where:{id:order.id},data:{status:p.data.status}});});if(!data)return res.status(404).json({error:"Order not found"});return res.json({data});}));
canteenRouter.post(base+"/orders/:orderId/serve",wrap(async(req,res)=>{const s=await scope(req,res,"canteen.serve");if(!s)return;const data=await withTenantContext(prisma,s,async tx=>{const order=await tx.canteenOrder.findFirst({where:{id:req.params.orderId,organizationId:s.organizationId,schoolId:s.schoolId}});if(!order)return null;if(["SERVED","CANCELLED"].includes(order.status))throw Object.assign(new Error("Order cannot be served"),{status:409});return tx.canteenOrder.update({where:{id:order.id},data:{status:"SERVED",servedBy:s.userId,servedAt:new Date()}});});if(!data)return res.status(404).json({error:"Order not found"});return res.json({data});}));
canteenRouter.get(base+"/stock",wrap(async(req,res)=>{const s=await scope(req,res);if(!s)return;const data=await withTenantContext(prisma,s,tx=>tx.canteenStockItem.findMany({where:{organizationId:s.organizationId,schoolId:s.schoolId},orderBy:{name:"asc"}}));return res.json({data});}));
canteenRouter.post(base+"/stock",wrap(async(req,res)=>{const s=await scope(req,res,"canteen.manage");if(!s)return;const p=z.object({name:z.string().trim().min(1).max(100),ingredientId:z.string().optional(),unit:z.string().trim().min(1).max(20).optional(),quantity:z.number().nonnegative(),reorderLevel:z.number().nonnegative().optional()}).safeParse(req.body);if(!p.success)return res.status(400).json({error:"Invalid stock item"});const data=await withTenantContext(prisma,s,async tx=>{if(p.data.ingredientId&&!await tx.canteenIngredient.findFirst({where:{id:p.data.ingredientId,organizationId:s.organizationId,schoolId:s.schoolId,isActive:true}}))throw Object.assign(new Error("Ingredient must belong to this school and be active"),{status:400});const stock=await tx.canteenStockItem.create({data:{organizationId:s.organizationId,schoolId:s.schoolId,name:p.data.name,ingredientId:p.data.ingredientId,unit:p.data.unit||"unit",quantity:p.data.quantity,reorderLevel:p.data.reorderLevel||0}});if(p.data.quantity>0)await tx.canteenStockLedger.create({data:{organizationId:s.organizationId,schoolId:s.schoolId,stockItemId:stock.id,movementType:"OPENING",quantityDelta:p.data.quantity,balanceAfter:p.data.quantity,unit:stock.unit,reason:"Opening stock",createdBy:s.userId}});return stock;});return res.status(201).json({data});}));
canteenRouter.patch(base+"/stock/:stockId",wrap(async(req,res)=>{const s=await scope(req,res,"canteen.manage");if(!s)return;const p=z.object({quantity:z.number().nonnegative(),reorderLevel:z.number().nonnegative().optional()}).safeParse(req.body);if(!p.success)return res.status(400).json({error:"Quantity must be non-negative"});const data=await withTenantContext(prisma,s,async tx=>{const item=await tx.canteenStockItem.findFirst({where:{id:req.params.stockId,organizationId:s.organizationId,schoolId:s.schoolId}});if(!item)return null;const delta=p.data.quantity-Number(item.quantity);if(delta!==0){const changed=await tx.canteenStockItem.updateMany({where:{id:item.id,organizationId:s.organizationId,schoolId:s.schoolId,quantity:item.quantity},data:{quantity:p.data.quantity,...(p.data.reorderLevel!==undefined?{reorderLevel:p.data.reorderLevel}:{})}});if(changed.count!==1)throw Object.assign(new Error("Stock changed concurrently; refresh and retry"),{status:409});await tx.canteenStockLedger.create({data:{organizationId:s.organizationId,schoolId:s.schoolId,stockItemId:item.id,movementType:"ADJUSTMENT",quantityDelta:delta,balanceAfter:p.data.quantity,unit:item.unit,reason:"Stock count adjustment",createdBy:s.userId}});}else if(p.data.reorderLevel!==undefined)await tx.canteenStockItem.update({where:{id:item.id},data:{reorderLevel:p.data.reorderLevel}});return tx.canteenStockItem.findFirst({where:{id:item.id,organizationId:s.organizationId,schoolId:s.schoolId}});});if(!data)return res.status(404).json({error:"Stock item not found"});return res.json({data});}));

// P546: immutable stock movement ledger and atomic receipt/adjustment/recipe-consumption workflows.
canteenRouter.get(base+"/stock/ledger",wrap(async(req,res)=>{const s=await scope(req,res);if(!s)return;const data=await withTenantContext(prisma,s,tx=>tx.canteenStockLedger.findMany({where:{organizationId:s.organizationId,schoolId:s.schoolId,...(req.query.stockItemId?{stockItemId:String(req.query.stockItemId)}:{})},include:{stockItem:{select:{id:true,name:true,unit:true}}},orderBy:{createdAt:"desc"},take:500}));return res.json({data});}));
canteenRouter.get(base+"/stock/reconciliation",wrap(async(req,res)=>{const s=await scope(req,res);if(!s)return;const [items,totals]=await withTenantContext(prisma,s,tx=>Promise.all([tx.canteenStockItem.findMany({where:{organizationId:s.organizationId,schoolId:s.schoolId},orderBy:{name:"asc"}}),tx.canteenStockLedger.groupBy({by:["stockItemId"],where:{organizationId:s.organizationId,schoolId:s.schoolId},_sum:{quantityDelta:true}})]));const data=items.map(item=>{const ledger=Number(totals.find(t=>t.stockItemId===item.id)?._sum.quantityDelta||0),current=Number(item.quantity);return {stockItemId:item.id,name:item.name,unit:item.unit,currentQuantity:current,ledgerQuantity:ledger,difference:current-ledger,reconciled:Math.abs(current-ledger)<0.0005};});return res.json({data:{items:data,discrepancyCount:data.filter(x=>!x.reconciled).length}});}));
canteenRouter.post(base+"/stock/:stockId/receipts",wrap(async(req,res)=>{const s=await scope(req,res,"canteen.manage");if(!s)return;const p=z.object({quantity:z.number().positive().max(100000000),reason:z.string().trim().min(1).max(500).optional(),referenceId:z.string().max(100).optional()}).safeParse(req.body);if(!p.success)return res.status(400).json({error:"Receipt quantity must be positive",details:p.error.flatten()});const data=await withTenantContext(prisma,s,async tx=>{const item=await tx.canteenStockItem.findFirst({where:{id:req.params.stockId,organizationId:s.organizationId,schoolId:s.schoolId}});if(!item)return null;const updated=await tx.canteenStockItem.update({where:{id:item.id},data:{quantity:{increment:p.data.quantity}}});await tx.canteenStockLedger.create({data:{organizationId:s.organizationId,schoolId:s.schoolId,stockItemId:item.id,movementType:"RECEIPT",quantityDelta:p.data.quantity,balanceAfter:updated.quantity,unit:item.unit,referenceType:"RECEIPT",referenceId:p.data.referenceId,reason:p.data.reason,createdBy:s.userId}});return updated;});if(!data)return res.status(404).json({error:"Stock item not found"});return res.status(201).json({data});}));
canteenRouter.post(base+"/stock/:stockId/adjustments",wrap(async(req,res)=>{const s=await scope(req,res,"canteen.manage");if(!s)return;const p=z.object({delta:z.number().max(100000000).min(-100000000).refine(v=>v!==0,"Adjustment cannot be zero"),reason:z.string().trim().min(1).max(500)}).safeParse(req.body);if(!p.success)return res.status(400).json({error:"Adjustment must be non-zero and include a reason",details:p.error.flatten()});const data=await withTenantContext(prisma,s,async tx=>{const item=await tx.canteenStockItem.findFirst({where:{id:req.params.stockId,organizationId:s.organizationId,schoolId:s.schoolId}});if(!item)return null;const newQty=Number(item.quantity)+p.data.delta;if(newQty<0)throw Object.assign(new Error("Adjustment would result in negative stock"),{status:409});const updated=await tx.canteenStockItem.updateMany({where:{id:item.id,organizationId:s.organizationId,schoolId:s.schoolId,quantity:item.quantity},data:{quantity:newQty}});if(updated.count!==1)throw Object.assign(new Error("Stock changed concurrently; refresh and retry"),{status:409});const balance=await tx.canteenStockItem.findFirst({where:{id:item.id},select:{quantity:true}});await tx.canteenStockLedger.create({data:{organizationId:s.organizationId,schoolId:s.schoolId,stockItemId:item.id,movementType:"ADJUSTMENT",quantityDelta:p.data.delta,balanceAfter:balance!.quantity,unit:item.unit,reason:p.data.reason,createdBy:s.userId}});return tx.canteenStockItem.findFirst({where:{id:item.id}});});if(!data)return res.status(404).json({error:"Stock item not found"});return res.json({data});}));
canteenRouter.post(base+"/recipes/:recipeId/consume",wrap(async(req,res)=>{const s=await scope(req,res,"canteen.manage");if(!s)return;const p=z.object({productionQuantity:z.number().positive().max(1000000),referenceId:z.string().max(100).optional(),reason:z.string().max(500).optional()}).safeParse(req.body);if(!p.success)return res.status(400).json({error:"Production quantity must be positive",details:p.error.flatten()});const result=await withTenantContext(prisma,s,async tx=>{const recipe=await tx.canteenRecipe.findFirst({where:{id:req.params.recipeId,organizationId:s.organizationId,schoolId:s.schoolId,isActive:true},include:{ingredients:{include:{ingredient:true}}}});if(!recipe)throw Object.assign(new Error("Recipe not found"),{status:404});const yieldQty=Number(recipe.yieldQuantity);if(yieldQty<=0)throw Object.assign(new Error("Recipe yield must be positive"),{status:400});const needs=recipe.ingredients.map(ri=>({ingredientId:ri.ingredientId,name:ri.ingredient.name,unit:ri.unit,quantity:Number(ri.quantity)*p.data.productionQuantity/yieldQty}));const stocks=await tx.canteenStockItem.findMany({where:{organizationId:s.organizationId,schoolId:s.schoolId,ingredientId:{in:needs.map(n=>n.ingredientId)}}});for(const need of needs){const stock=stocks.find(st=>st.ingredientId===need.ingredientId);if(!stock)throw Object.assign(new Error(`No stock item linked for ingredient ${need.name}`),{status:409});if(stock.unit!==need.unit)throw Object.assign(new Error(`Unit mismatch for ${need.name}: recipe uses ${need.unit}, stock uses ${stock.unit}`),{status:400});if(Number(stock.quantity)<need.quantity)throw Object.assign(new Error(`Insufficient stock for ${need.name}`),{status:409});}const entries=[];for(const need of needs){const stock=stocks.find(st=>st.ingredientId===need.ingredientId)!;const update=await tx.canteenStockItem.updateMany({where:{id:stock.id,organizationId:s.organizationId,schoolId:s.schoolId,quantity:{gte:need.quantity}},data:{quantity:{decrement:need.quantity}}});if(update.count!==1)throw Object.assign(new Error(`Insufficient or concurrently changed stock for ${need.name}`),{status:409});const fresh=await tx.canteenStockItem.findFirst({where:{id:stock.id},select:{quantity:true}});const ledger=await tx.canteenStockLedger.create({data:{organizationId:s.organizationId,schoolId:s.schoolId,stockItemId:stock.id,movementType:"CONSUMPTION",quantityDelta:-need.quantity,balanceAfter:fresh!.quantity,unit:stock.unit,referenceType:"PRODUCTION",referenceId:p.data.referenceId,reason:p.data.reason||`Production of ${p.data.productionQuantity} ${recipe.yieldUnit} for ${recipe.name}`,createdBy:s.userId}});entries.push(ledger);}return {recipeId:recipe.id,productionQuantity:p.data.productionQuantity,yieldUnit:recipe.yieldUnit,consumed:entries};});return res.status(201).json({data:result});}));

// P545: tenant-scoped recipe and ingredient catalogue with nutrition/allergen metadata.
const ingredientSchema = z.object({
  name: z.string().trim().min(1).max(100),
  unit: z.string().trim().min(1).max(20).default("g"),
  category: z.string().trim().max(40).optional(),
  allergens: z.array(z.string().trim().min(1).max(40)).max(30).optional(),
});
const recipeIngredientSchema = z.object({
  ingredientId: z.string().min(1),
  quantity: z.number().positive().max(1000000),
  unit: z.string().trim().min(1).max(20),
  preparationNotes: z.string().max(500).optional(),
});
const recipeSchema = z.object({
  name: z.string().trim().min(1).max(120),
  description: z.string().max(1000).optional(),
  yieldQuantity: z.number().positive().max(100000).default(1),
  yieldUnit: z.string().trim().min(1).max(30).default("serving"),
  nutrition: z.object({
    calories: z.number().nonnegative().optional(),
    proteinGrams: z.number().nonnegative().optional(),
    carbohydratesGrams: z.number().nonnegative().optional(),
    fatGrams: z.number().nonnegative().optional(),
    fiberGrams: z.number().nonnegative().optional(),
    sodiumMg: z.number().nonnegative().optional(),
  }).partial().optional(),
  allergens: z.array(z.string().trim().min(1).max(40)).max(30).optional(),
  dietaryTags: z.array(z.string().trim().min(1).max(30)).max(30).optional(),
  ingredients: z.array(recipeIngredientSchema).min(1).max(100),
});

canteenRouter.get(base+"/ingredients",wrap(async(req,res)=>{
  const s=await scope(req,res);if(!s)return;
  const data=await withTenantContext(prisma,s,tx=>tx.canteenIngredient.findMany({where:{organizationId:s.organizationId,schoolId:s.schoolId,isActive:true},orderBy:{name:"asc"},take:500}));
  return res.json({data});
}));
canteenRouter.post(base+"/ingredients",wrap(async(req,res)=>{
  const s=await scope(req,res,"canteen.manage");if(!s)return;
  const p=ingredientSchema.safeParse(req.body);if(!p.success)return res.status(400).json({error:"Invalid ingredient",details:p.error.flatten()});
  const data=await withTenantContext(prisma,s,tx=>tx.canteenIngredient.create({data:{organizationId:s.organizationId,schoolId:s.schoolId,createdBy:s.userId,...p.data,allergens:p.data.allergens||[]}}));
  return res.status(201).json({data});
}));
canteenRouter.patch(base+"/ingredients/:ingredientId",wrap(async(req,res)=>{
  const s=await scope(req,res,"canteen.manage");if(!s)return;
  const p=ingredientSchema.partial().safeParse(req.body);if(!p.success)return res.status(400).json({error:"Invalid ingredient",details:p.error.flatten()});
  const data=await withTenantContext(prisma,s,async tx=>{const existing=await tx.canteenIngredient.findFirst({where:{id:req.params.ingredientId,organizationId:s.organizationId,schoolId:s.schoolId}});if(!existing)return null;return tx.canteenIngredient.update({where:{id:existing.id},data:p.data});});
  if(!data)return res.status(404).json({error:"Ingredient not found"});return res.json({data});
}));
canteenRouter.get(base+"/recipes",wrap(async(req,res)=>{
  const s=await scope(req,res);if(!s)return;
  const data=await withTenantContext(prisma,s,tx=>tx.canteenRecipe.findMany({where:{organizationId:s.organizationId,schoolId:s.schoolId},include:{ingredients:{include:{ingredient:true}}},orderBy:{name:"asc"},take:300}));
  return res.json({data});
}));
canteenRouter.post(base+"/recipes",wrap(async(req,res)=>{
  const s=await scope(req,res,"canteen.manage");if(!s)return;
  const p=recipeSchema.safeParse(req.body);if(!p.success)return res.status(400).json({error:"Invalid recipe",details:p.error.flatten()});
  const data=await withTenantContext(prisma,s,async tx=>{
    const ingredientIds=[...new Set(p.data.ingredients.map(i=>i.ingredientId))];
    const found=await tx.canteenIngredient.findMany({where:{id:{in:ingredientIds},organizationId:s.organizationId,schoolId:s.schoolId,isActive:true},select:{id:true}});
    if(found.length!==ingredientIds.length)throw Object.assign(new Error("Ingredients must belong to this school and be active"),{status:400});
    return tx.canteenRecipe.create({data:{organizationId:s.organizationId,schoolId:s.schoolId,createdBy:s.userId,name:p.data.name,description:p.data.description,yieldQuantity:p.data.yieldQuantity,yieldUnit:p.data.yieldUnit,nutrition:p.data.nutrition,allergens:p.data.allergens||[],dietaryTags:p.data.dietaryTags||[],ingredients:{create:p.data.ingredients.map(i=>({...i,organizationId:s.organizationId,schoolId:s.schoolId}))}},include:{ingredients:{include:{ingredient:true}}}});
  });
  return res.status(201).json({data});
}));
canteenRouter.patch(base+"/recipes/:recipeId",wrap(async(req,res)=>{
  const s=await scope(req,res,"canteen.manage");if(!s)return;
  const p=recipeSchema.partial().safeParse(req.body);if(!p.success)return res.status(400).json({error:"Invalid recipe update",details:p.error.flatten()});
  const data=await withTenantContext(prisma,s,async tx=>{
    const existing=await tx.canteenRecipe.findFirst({where:{id:req.params.recipeId,organizationId:s.organizationId,schoolId:s.schoolId}});if(!existing)return null;
    if(p.data.ingredients){
      const ids=[...new Set(p.data.ingredients.map(i=>i.ingredientId))];
      const found=await tx.canteenIngredient.findMany({where:{id:{in:ids},organizationId:s.organizationId,schoolId:s.schoolId,isActive:true},select:{id:true}});
      if(found.length!==ids.length)throw Object.assign(new Error("Ingredients must belong to this school and be active"),{status:400});
      await tx.canteenRecipeIngredient.deleteMany({where:{recipeId:existing.id,organizationId:s.organizationId,schoolId:s.schoolId}});
    }
    const {ingredients,...recipeData}=p.data;
    return tx.canteenRecipe.update({where:{id:existing.id},data:{...recipeData,...(ingredients?{ingredients:{create:ingredients.map(i=>({...i,organizationId:s.organizationId,schoolId:s.schoolId}))}}:{})},include:{ingredients:{include:{ingredient:true}}}});
  });
  if(!data)return res.status(404).json({error:"Recipe not found"});return res.json({data});
}));

// Student mobile: only the student's own verified linked account can place orders.
canteenRouter.get("/students/me/:organizationId/:schoolId/canteen/menu",wrap(async(req,res)=>{const userId=req.auth!.userId,organizationId=String(req.params.organizationId),schoolId=String(req.params.schoolId);const link=await withPlatformContext(prisma,tx=>tx.studentAccountLink.findFirst({where:{organizationId,schoolId,userId,isActive:true,student:{status:"ACTIVE"}},select:{studentId:true}}));if(!link)return res.status(403).json({error:"Active student account link required"});const today=new Date();today.setHours(0,0,0,0);const data=await withTenantContext(prisma,{organizationId,schoolId,userId},tx=>tx.canteenMenuItem.findMany({where:{organizationId,schoolId,isAvailable:true,OR:[{availableOn:null},{availableOn:today}]},orderBy:[{category:"asc"},{name:"asc"}]}));return res.json({data});}));
canteenRouter.post("/students/me/:organizationId/:schoolId/canteen/orders",wrap(async(req,res)=>{const userId=req.auth!.userId,organizationId=String(req.params.organizationId),schoolId=String(req.params.schoolId);const p=z.object({orderDate:z.string().datetime(),notes:z.string().max(500).optional(),items:z.array(z.object({menuItemId:z.string().min(1),quantity:z.number().int().min(1).max(50)})).min(1).max(20)}).safeParse(req.body);if(!p.success)return res.status(400).json({error:"Invalid order",details:p.error.flatten()});const link=await withPlatformContext(prisma,tx=>tx.studentAccountLink.findFirst({where:{organizationId,schoolId,userId,isActive:true,student:{status:"ACTIVE"}},select:{studentId:true}}));if(!link)return res.status(403).json({error:"Active student account link required"});const data=await withTenantContext(prisma,{organizationId,schoolId,userId},async tx=>{const menu=await tx.canteenMenuItem.findMany({where:{organizationId,schoolId,id:{in:p.data.items.map(i=>i.menuItemId)},isAvailable:true}});if(menu.length!==new Set(p.data.items.map(i=>i.menuItemId)).size)throw Object.assign(new Error("One or more menu items are unavailable"),{status:400});const safety=await canteenAllergenCheck(tx,organizationId,schoolId,link.studentId,menu);if(safety.conflicts.length)throw Object.assign(new Error("Order blocked by dietary/allergen safety profile"),{status:409,details:safety.conflicts});const items=p.data.items.map(i=>{const m=menu.find(x=>x.id===i.menuItemId)!;const unit=Number(m.price);return {menuItemId:m.id,itemName:m.name,quantity:i.quantity,unitPrice:unit,lineTotal:unit*i.quantity};});const total=items.reduce((sum,i)=>sum+i.lineTotal,0);return tx.canteenOrder.create({data:{organizationId,schoolId,studentId:link.studentId,orderDate:new Date(p.data.orderDate),notes:p.data.notes,createdBy:userId,total,items:{create:items}},include:{items:true}});});return res.status(201).json({data});}));
// Parent mobile: restrict menu/order access to students linked to the authenticated guardian.
canteenRouter.get("/parents/me/:organizationId/:schoolId/canteen/menu",wrap(async(req,res)=>{const userId=req.auth!.userId,organizationId=String(req.params.organizationId),schoolId=String(req.params.schoolId);const studentIds=await parentCanteenStudentIds(userId,organizationId,schoolId);if(!studentIds.length)return res.status(403).json({error:"Verified guardian membership, accepted consent and parent canteen permission are required"});const today=new Date();today.setHours(0,0,0,0);const data=await withTenantContext(prisma,{organizationId,schoolId,userId},tx=>tx.canteenMenuItem.findMany({where:{organizationId,schoolId,isAvailable:true,OR:[{availableOn:null},{availableOn:today}]},orderBy:[{category:"asc"},{name:"asc"}]}));return res.json({data,studentIds});}));
canteenRouter.post("/parents/me/:organizationId/:schoolId/canteen/orders",wrap(async(req,res)=>{const userId=req.auth!.userId,organizationId=String(req.params.organizationId),schoolId=String(req.params.schoolId);const p=z.object({studentId:z.string().min(1),orderDate:z.string().datetime(),notes:z.string().max(500).optional(),items:z.array(z.object({menuItemId:z.string().min(1),quantity:z.number().int().min(1).max(50)})).min(1).max(20)}).safeParse(req.body);if(!p.success)return res.status(400).json({error:"Invalid order",details:p.error.flatten()});const studentIds=await parentCanteenStudentIds(userId,organizationId,schoolId);if(!studentIds.includes(p.data.studentId))return res.status(403).json({error:"Guardian is not consented and linked to this student"});const data=await withTenantContext(prisma,{organizationId,schoolId,userId},async tx=>{const menu=await tx.canteenMenuItem.findMany({where:{organizationId,schoolId,id:{in:p.data.items.map(i=>i.menuItemId)},isAvailable:true}});if(menu.length!==new Set(p.data.items.map(i=>i.menuItemId)).size)throw Object.assign(new Error("One or more menu items are unavailable"),{status:400});const safety=await canteenAllergenCheck(tx,organizationId,schoolId,p.data.studentId,menu);if(safety.conflicts.length)throw Object.assign(new Error("Order blocked by dietary/allergen safety profile"),{status:409,details:safety.conflicts});const items=p.data.items.map(i=>{const m=menu.find(x=>x.id===i.menuItemId)!;const unit=Number(m.price);return {menuItemId:m.id,itemName:m.name,quantity:i.quantity,unitPrice:unit,lineTotal:unit*i.quantity};});const total=items.reduce((sum,i)=>sum+i.lineTotal,0);return tx.canteenOrder.create({data:{organizationId,schoolId,studentId:p.data.studentId,orderDate:new Date(p.data.orderDate),notes:p.data.notes,createdBy:userId,total,items:{create:items}},include:{items:true}});});return res.status(201).json({data});}));

canteenRouter.patch(base+"/orders/:orderId/payment",wrap(async(req,res)=>{const s=await scope(req,res,"canteen.manage");if(!s)return;const p=z.object({paymentMethod:z.enum(["CASH","CARD","UPI","ONLINE","OTHER"]),paymentReference:z.string().max(120).optional()}).safeParse(req.body);if(!p.success)return res.status(400).json({error:"Invalid payment details"});const data=await withTenantContext(prisma,s,async tx=>{const order=await tx.canteenOrder.findFirst({where:{id:req.params.orderId,organizationId:s.organizationId,schoolId:s.schoolId}});if(!order)return null;if(order.paymentStatus==="PAID")throw Object.assign(new Error("Order is already paid"),{status:409});return tx.canteenOrder.update({where:{id:order.id},data:{paymentStatus:"PAID",paymentMethod:p.data.paymentMethod,paymentReference:p.data.paymentReference,paidAt:new Date()}});});if(!data)return res.status(404).json({error:"Order not found"});return res.json({data});}));
canteenRouter.get("/students/me/:organizationId/:schoolId/canteen/orders",wrap(async(req,res)=>{const userId=req.auth!.userId,organizationId=String(req.params.organizationId),schoolId=String(req.params.schoolId);const link=await withPlatformContext(prisma,tx=>tx.studentAccountLink.findFirst({where:{organizationId,schoolId,userId,isActive:true,student:{status:"ACTIVE"}},select:{studentId:true}}));if(!link)return res.status(403).json({error:"Active student account link required"});const data=await withTenantContext(prisma,{organizationId,schoolId,userId},tx=>tx.canteenOrder.findMany({where:{organizationId,schoolId,studentId:link.studentId},include:{items:true},orderBy:{createdAt:"desc"},take:50}));return res.json({data});}));
canteenRouter.get("/parents/me/:organizationId/:schoolId/canteen/orders",wrap(async(req,res)=>{const userId=req.auth!.userId,organizationId=String(req.params.organizationId),schoolId=String(req.params.schoolId);const studentIds=await parentCanteenStudentIds(userId,organizationId,schoolId);if(!studentIds.length)return res.status(403).json({error:"Verified guardian membership, accepted consent and parent canteen permission are required"});const data=await withTenantContext(prisma,{organizationId,schoolId,userId},tx=>tx.canteenOrder.findMany({where:{organizationId,schoolId,studentId:{in:studentIds}},include:{items:true},orderBy:{createdAt:"desc"},take:100}));return res.json({data});}));


// P547 procurement APIs: supplier directory, purchase orders and partial lot receiving.
canteenRouter.get(base+"/suppliers",wrap(async(req,res)=>{const s=await scope(req,res);if(!s)return;const data=await withTenantContext(prisma,s,tx=>tx.canteenSupplier.findMany({where:{organizationId:s.organizationId,schoolId:s.schoolId},orderBy:{name:"asc"},take:500}));return res.json({data});}));
canteenRouter.post(base+"/suppliers",wrap(async(req,res)=>{const s=await scope(req,res,"canteen.manage");if(!s)return;const p=z.object({name:z.string().trim().min(1).max(120),contactName:z.string().max(120).optional(),phone:z.string().max(40).optional(),email:z.string().email().max(180).optional(),address:z.string().max(500).optional()}).safeParse(req.body);if(!p.success)return res.status(400).json({error:"Invalid supplier",details:p.error.flatten()});const data=await withTenantContext(prisma,s,tx=>tx.canteenSupplier.create({data:{organizationId:s.organizationId,schoolId:s.schoolId,createdBy:s.userId,...p.data}}));return res.status(201).json({data});}));
canteenRouter.get(base+"/purchase-orders",wrap(async(req,res)=>{const s=await scope(req,res);if(!s)return;const data=await withTenantContext(prisma,s,tx=>tx.canteenPurchaseOrder.findMany({where:{organizationId:s.organizationId,schoolId:s.schoolId},include:{supplier:true,lines:true},orderBy:{createdAt:"desc"},take:200}));return res.json({data});}));
canteenRouter.post(base+"/purchase-orders",wrap(async(req,res)=>{const s=await scope(req,res,"canteen.manage");if(!s)return;const p=z.object({supplierId:z.string().min(1),orderNumber:z.string().trim().min(1).max(60),expectedAt:z.string().datetime().optional(),notes:z.string().max(1000).optional(),lines:z.array(z.object({stockItemId:z.string().min(1),orderedQuantity:z.number().positive().max(1000000),unitCost:z.number().nonnegative().max(10000000)})).min(1).max(100)}).safeParse(req.body);if(!p.success)return res.status(400).json({error:"Invalid purchase order",details:p.error.flatten()});const data=await withTenantContext(prisma,s,async tx=>{const supplier=await tx.canteenSupplier.findFirst({where:{id:p.data.supplierId,organizationId:s.organizationId,schoolId:s.schoolId,isActive:true}});if(!supplier)throw Object.assign(new Error("Active supplier not found"),{status:404});const stockIds=[...new Set(p.data.lines.map(l=>l.stockItemId))];const stockItems=await tx.canteenStockItem.findMany({where:{id:{in:stockIds},organizationId:s.organizationId,schoolId:s.schoolId},select:{id:true}});if(stockItems.length!==stockIds.length)throw Object.assign(new Error("All stock items must belong to this school"),{status:400});return tx.canteenPurchaseOrder.create({data:{organizationId:s.organizationId,schoolId:s.schoolId,supplierId:supplier.id,orderNumber:p.data.orderNumber,expectedAt:p.data.expectedAt?new Date(p.data.expectedAt):null,notes:p.data.notes,createdBy:s.userId,lines:{create:p.data.lines.map(l=>({...l,organizationId:s.organizationId,schoolId:s.schoolId}))}},include:{supplier:true,lines:true}});});return res.status(201).json({data});}));
canteenRouter.post(base+"/purchase-orders/:orderId/receive",wrap(async(req,res)=>{const s=await scope(req,res,"canteen.manage");if(!s)return;const p=z.object({lineId:z.string().min(1),quantity:z.number().positive().max(1000000),lotCode:z.string().trim().min(1).max(80),expiryDate:z.string().datetime().optional(),notes:z.string().max(500).optional()}).safeParse(req.body);if(!p.success)return res.status(400).json({error:"Invalid receiving record",details:p.error.flatten()});const result=await withTenantContext(prisma,s,async tx=>{const order=await tx.canteenPurchaseOrder.findFirst({where:{id:req.params.orderId,organizationId:s.organizationId,schoolId:s.schoolId},include:{supplier:true,lines:true}});if(!order)throw Object.assign(new Error("Purchase order not found"),{status:404});if(["CANCELLED","CLOSED"].includes(order.status))throw Object.assign(new Error("Purchase order is not receivable"),{status:409});const line=order.lines.find(l=>l.id===p.data.lineId);if(!line)throw Object.assign(new Error("Purchase order line not found"),{status:404});const outstanding=Number(line.orderedQuantity)-Number(line.receivedQuantity);if(p.data.quantity>outstanding+0.0005)throw Object.assign(new Error("Receiving quantity exceeds outstanding quantity"),{status:409});const stock=await tx.canteenStockItem.findFirst({where:{id:line.stockItemId,organizationId:s.organizationId,schoolId:s.schoolId}});if(!stock)throw Object.assign(new Error("Stock item not found"),{status:404});const updatedStock=await tx.canteenStockItem.update({where:{id:stock.id},data:{quantity:{increment:p.data.quantity}}});const lot=await tx.canteenStockLot.create({data:{organizationId:s.organizationId,schoolId:s.schoolId,stockItemId:stock.id,purchaseOrderId:order.id,purchaseOrderLineId:line.id,lotCode:p.data.lotCode,receivedQuantity:p.data.quantity,remainingQuantity:p.data.quantity,unit:stock.unit,expiryDate:p.data.expiryDate?new Date(p.data.expiryDate):null,supplierName:order.supplier.name,notes:p.data.notes,createdBy:s.userId}});await tx.canteenStockLedger.create({data:{organizationId:s.organizationId,schoolId:s.schoolId,stockItemId:stock.id,movementType:"RECEIPT",quantityDelta:p.data.quantity,balanceAfter:updatedStock.quantity,unit:stock.unit,referenceType:"PURCHASE_ORDER",referenceId:order.id,reason:`PO ${order.orderNumber} receiving lot ${p.data.lotCode}`,createdBy:s.userId}});const updatedLine=await tx.canteenPurchaseOrderLine.update({where:{id:line.id},data:{receivedQuantity:{increment:p.data.quantity}}});const allLines=await tx.canteenPurchaseOrderLine.findMany({where:{purchaseOrderId:order.id,organizationId:s.organizationId,schoolId:s.schoolId}});const complete=allLines.every(l=>Number(l.receivedQuantity)+(l.id===line.id?p.data.quantity:0)>=Number(l.orderedQuantity)-0.0005);await tx.canteenPurchaseOrder.update({where:{id:order.id},data:{status:complete?"RECEIVED":"PARTIALLY_RECEIVED"}});return {lot,stock:updatedStock,line:updatedLine,status:complete?"RECEIVED":"PARTIALLY_RECEIVED",outstandingAfter:Number(line.orderedQuantity)-Number(updatedLine.receivedQuantity)};});return res.status(201).json({data:result});}));
canteenRouter.get(base+"/stock/lots",wrap(async(req,res)=>{const s=await scope(req,res);if(!s)return;const filter=String(req.query.filter||"all"),today=new Date(),soon=new Date(today);soon.setDate(soon.getDate()+30);const where:any={organizationId:s.organizationId,schoolId:s.schoolId};if(filter==="expired")where.expiryDate={lt:today};else if(filter==="expiring")where.expiryDate={gte:today,lt:soon};const data=await withTenantContext(prisma,s,tx=>tx.canteenStockLot.findMany({where,include:{stockItem:{select:{id:true,name:true,unit:true}}},orderBy:[{expiryDate:"asc"},{receivedAt:"desc"}],take:500}));return res.json({data});}));
// P548 production planning, batch execution, serving reconciliation and wastage capture.
canteenRouter.get(base+"/production/batches",wrap(async(req,res)=>{const s=await scope(req,res);if(!s)return;const data=await withTenantContext(prisma,s,tx=>tx.canteenProductionBatch.findMany({where:{organizationId:s.organizationId,schoolId:s.schoolId,...(req.query.status?{status:String(req.query.status)}:{})},include:{recipe:{select:{id:true,name:true,yieldUnit:true}},wastageRecords:true},orderBy:[{plannedFor:"asc"},{createdAt:"desc"}],take:500}));return res.json({data});}));
canteenRouter.post(base+"/production/batches",wrap(async(req,res)=>{const s=await scope(req,res,"canteen.manage");if(!s)return;const p=z.object({recipeId:z.string().min(1),plannedQuantity:z.number().positive().max(1000000),plannedFor:z.string().datetime().optional(),notes:z.string().max(1000).optional()}).safeParse(req.body);if(!p.success)return res.status(400).json({error:"Invalid production plan",details:p.error.flatten()});const data=await withTenantContext(prisma,s,async tx=>{const recipe=await tx.canteenRecipe.findFirst({where:{id:p.data.recipeId,organizationId:s.organizationId,schoolId:s.schoolId,isActive:true}});if(!recipe)throw Object.assign(new Error("Active recipe not found"),{status:404});return tx.canteenProductionBatch.create({data:{organizationId:s.organizationId,schoolId:s.schoolId,recipeId:recipe.id,plannedQuantity:p.data.plannedQuantity,plannedFor:p.data.plannedFor?new Date(p.data.plannedFor):null,notes:p.data.notes,createdBy:s.userId},include:{recipe:{select:{id:true,name:true,yieldUnit:true}}}});});return res.status(201).json({data});}));
canteenRouter.post(base+"/production/batches/:batchId/start",wrap(async(req,res)=>{const s=await scope(req,res,"canteen.manage");if(!s)return;const result=await withTenantContext(prisma,s,async tx=>{const batch=await tx.canteenProductionBatch.findFirst({where:{id:req.params.batchId,organizationId:s.organizationId,schoolId:s.schoolId},include:{recipe:{include:{ingredients:{include:{ingredient:true}}}}}});if(!batch)throw Object.assign(new Error("Production batch not found"),{status:404});if(batch.status!=="PLANNED")throw Object.assign(new Error("Only planned batches can be started"),{status:409});const qty=Number(batch.plannedQuantity),yieldQty=Number(batch.recipe.yieldQuantity);if(yieldQty<=0)throw Object.assign(new Error("Recipe yield must be positive"),{status:400});const needs=batch.recipe.ingredients.map(ri=>({ingredientId:ri.ingredientId,name:ri.ingredient.name,unit:ri.unit,quantity:Number(ri.quantity)*qty/yieldQty}));const stocks=await tx.canteenStockItem.findMany({where:{organizationId:s.organizationId,schoolId:s.schoolId,ingredientId:{in:needs.map(n=>n.ingredientId)}}});for(const need of needs){const stock=stocks.find(st=>st.ingredientId===need.ingredientId);if(!stock)throw Object.assign(new Error(`No stock item linked for ${need.name}`),{status:409});if(stock.unit!==need.unit)throw Object.assign(new Error(`Unit mismatch for ${need.name}`),{status:400});if(Number(stock.quantity)<need.quantity)throw Object.assign(new Error(`Insufficient stock for ${need.name}`),{status:409});}for(const need of needs){const stock=stocks.find(st=>st.ingredientId===need.ingredientId);const upd=await tx.canteenStockItem.updateMany({where:{id:stock.id,organizationId:s.organizationId,schoolId:s.schoolId,quantity:{gte:need.quantity}},data:{quantity:{decrement:need.quantity}}});if(upd.count!==1)throw Object.assign(new Error(`Stock changed or insufficient for ${need.name}`),{status:409});const fresh=await tx.canteenStockItem.findFirst({where:{id:stock.id},select:{quantity:true}});await tx.canteenStockLedger.create({data:{organizationId:s.organizationId,schoolId:s.schoolId,stockItemId:stock.id,movementType:"CONSUMPTION",quantityDelta:-need.quantity,balanceAfter:fresh.quantity,unit:stock.unit,referenceType:"PRODUCTION_BATCH",referenceId:batch.id,reason:`Production batch ${batch.id}: planned ${qty} ${batch.recipe.yieldUnit}`,createdBy:s.userId}});}return tx.canteenProductionBatch.update({where:{id:batch.id},data:{status:"IN_PROGRESS",producedQuantity:qty,startedAt:new Date()},include:{recipe:{select:{id:true,name:true,yieldUnit:true}}}});});return res.json({data:result});}));
canteenRouter.post(base+"/production/batches/:batchId/wastage",wrap(async(req,res)=>{const s=await scope(req,res,"canteen.manage");if(!s)return;const p=z.object({quantity:z.number().positive().max(1000000),reason:z.string().trim().min(1).max(300)}).safeParse(req.body);if(!p.success)return res.status(400).json({error:"Wastage quantity and reason are required",details:p.error.flatten()});const result=await withTenantContext(prisma,s,async tx=>{const batch=await tx.canteenProductionBatch.findFirst({where:{id:req.params.batchId,organizationId:s.organizationId,schoolId:s.schoolId}});if(!batch)throw Object.assign(new Error("Production batch not found"),{status:404});if(batch.status!=="IN_PROGRESS")throw Object.assign(new Error("Wastage can only be recorded while production is in progress"),{status:409});if(Number(batch.wastageQuantity)+p.data.quantity>Number(batch.producedQuantity||0)+0.0005)throw Object.assign(new Error("Wastage exceeds produced quantity"),{status:409});const record=await tx.canteenProductionWastage.create({data:{organizationId:s.organizationId,schoolId:s.schoolId,batchId:batch.id,quantity:p.data.quantity,reason:p.data.reason,createdBy:s.userId}});await tx.canteenProductionBatch.update({where:{id:batch.id},data:{wastageQuantity:{increment:p.data.quantity}}});return record;});return res.status(201).json({data:result});}));
canteenRouter.patch(base+"/production/batches/:batchId/complete",wrap(async(req,res)=>{const s=await scope(req,res,"canteen.manage");if(!s)return;const p=z.object({servedQuantity:z.number().nonnegative().max(1000000),notes:z.string().max(1000).optional()}).safeParse(req.body);if(!p.success)return res.status(400).json({error:"Invalid served quantity",details:p.error.flatten()});const data=await withTenantContext(prisma,s,async tx=>{const batch=await tx.canteenProductionBatch.findFirst({where:{id:req.params.batchId,organizationId:s.organizationId,schoolId:s.schoolId}});if(!batch)throw Object.assign(new Error("Production batch not found"),{status:404});if(batch.status!=="IN_PROGRESS")throw Object.assign(new Error("Only in-progress batches can be completed"),{status:409});const produced=Number(batch.producedQuantity||0),wasted=Number(batch.wastageQuantity);if(p.data.servedQuantity+wasted>produced+0.0005)throw Object.assign(new Error("Served plus wastage cannot exceed produced quantity"),{status:409});return tx.canteenProductionBatch.update({where:{id:batch.id},data:{servedQuantity:p.data.servedQuantity,status:"COMPLETED",completedAt:new Date(),notes:p.data.notes??batch.notes}});});return res.json({data});}));

// P549 meal preorder lifecycle: school policy, student/parent preorders, cancellation and refund tracking.
function serviceCutoff(serviceDate:Date,serviceTime:string,minutes:number){const [hh,mm]=serviceTime.split(":").map(Number);const at=new Date(serviceDate);at.setHours(hh||0,mm||0,0,0);at.setMinutes(at.getMinutes()-minutes);return at;}
canteenRouter.get(base+"/preorders/policy",wrap(async(req,res)=>{const s=await scope(req,res);if(!s)return;const policy=await withTenantContext(prisma,s,tx=>tx.canteenPreorderPolicy.findUnique({where:{organizationId_schoolId:{organizationId:s.organizationId,schoolId:s.schoolId}}}));return res.json({data:policy});}));
canteenRouter.put(base+"/preorders/policy",wrap(async(req,res)=>{const s=await scope(req,res,"canteen.manage");if(!s)return;const p=z.object({serviceTime:z.string().regex(/^([01]\d|2[0-3]):[0-5]\d$/).optional(),cutoffMinutesBeforeService:z.number().int().min(0).max(1440).optional(),allowCancellation:z.boolean().optional(),cancellationCutoffMinutes:z.number().int().min(0).max(1440).optional(),refundMode:z.enum(["MANUAL"]).optional(),isActive:z.boolean().optional()}).safeParse(req.body);if(!p.success)return res.status(400).json({error:"Invalid preorder policy",details:p.error.flatten()});const data=await withTenantContext(prisma,s,tx=>tx.canteenPreorderPolicy.upsert({where:{organizationId_schoolId:{organizationId:s.organizationId,schoolId:s.schoolId}},create:{organizationId:s.organizationId,schoolId:s.schoolId,updatedBy:s.userId,...p.data},update:{updatedBy:s.userId,...p.data}}));return res.json({data});}));
async function createCanteenPreorder(scopeData:any,studentId:string,serviceDate:string,items:any[],notes:string|undefined,createdBy:string){return withTenantContext(prisma,scopeData,async tx=>{const student=await tx.student.findFirst({where:{id:studentId,organizationId:scopeData.organizationId,schoolId:scopeData.schoolId,status:"ACTIVE"},select:{id:true}});if(!student)throw Object.assign(new Error("Active student not found"),{status:404});const date=new Date(serviceDate);date.setHours(0,0,0,0);if(date<new Date(new Date().setHours(0,0,0,0)))throw Object.assign(new Error("Preorders must be for today or a future service date"),{status:400});const policy=await tx.canteenPreorderPolicy.findUnique({where:{organizationId_schoolId:{organizationId:scopeData.organizationId,schoolId:scopeData.schoolId}}});if(policy&&!policy.isActive)throw Object.assign(new Error("Meal preordering is disabled"),{status:409});const serviceTime=policy?.serviceTime||"12:00",cutoffMinutes=policy?.cutoffMinutesBeforeService??60;if(new Date()>=serviceCutoff(date,serviceTime,cutoffMinutes))throw Object.assign(new Error("Preorder cutoff has passed"),{status:409});const menu=await tx.canteenMenuItem.findMany({where:{organizationId:scopeData.organizationId,schoolId:scopeData.schoolId,id:{in:items.map(i=>i.menuItemId)},isAvailable:true,OR:[{availableOn:null},{availableOn:date}]}});if(menu.length!==new Set(items.map(i=>i.menuItemId)).size)throw Object.assign(new Error("One or more menu items unavailable for the selected service date"),{status:400});const orderItems=items.map(i=>{const m=menu.find(x=>x.id===i.menuItemId)!;const price=Number(m.price);return {menuItemId:m.id,itemName:m.name,quantity:i.quantity,unitPrice:price,lineTotal:price*i.quantity};});const total=orderItems.reduce((sum,i)=>sum+i.lineTotal,0);return tx.canteenPreorder.create({data:{organizationId:scopeData.organizationId,schoolId:scopeData.schoolId,studentId,serviceDate:date,notes,createdBy,status:"PLACED",paymentStatus:"UNPAID",total,items:{create:orderItems}},include:{items:true}});});}
const preorderItemsSchema=z.array(z.object({menuItemId:z.string().min(1),quantity:z.number().int().min(1).max(100)})).min(1).max(30);
canteenRouter.post("/students/me/:organizationId/:schoolId/canteen/preorders",wrap(async(req,res)=>{const userId=req.auth!.userId,organizationId=String(req.params.organizationId),schoolId=String(req.params.schoolId);const p=z.object({serviceDate:z.string().datetime(),notes:z.string().max(500).optional(),items:preorderItemsSchema}).safeParse(req.body);if(!p.success)return res.status(400).json({error:"Invalid preorder",details:p.error.flatten()});const link=await withPlatformContext(prisma,tx=>tx.studentAccountLink.findFirst({where:{organizationId,schoolId,userId,isActive:true,student:{status:"ACTIVE"}},select:{studentId:true}}));if(!link)return res.status(403).json({error:"Active student account link required"});const data=await createCanteenPreorder({organizationId,schoolId,userId},link.studentId,p.data.serviceDate,p.data.items,p.data.notes,userId);return res.status(201).json({data});}));
canteenRouter.post("/parents/me/:organizationId/:schoolId/canteen/preorders",wrap(async(req,res)=>{const userId=req.auth!.userId,organizationId=String(req.params.organizationId),schoolId=String(req.params.schoolId);const p=z.object({studentId:z.string().min(1),serviceDate:z.string().datetime(),notes:z.string().max(500).optional(),items:preorderItemsSchema}).safeParse(req.body);if(!p.success)return res.status(400).json({error:"Invalid preorder",details:p.error.flatten()});const studentIds=await parentCanteenStudentIds(userId,organizationId,schoolId);if(!studentIds.includes(p.data.studentId))return res.status(403).json({error:"Guardian is not verified, consented and linked to this student"});const data=await createCanteenPreorder({organizationId,schoolId,userId},p.data.studentId,p.data.serviceDate,p.data.items,p.data.notes,userId);return res.status(201).json({data});}));
canteenRouter.get(base+"/preorders",wrap(async(req,res)=>{const s=await scope(req,res);if(!s)return;const data=await withTenantContext(prisma,s,tx=>tx.canteenPreorder.findMany({where:{organizationId:s.organizationId,schoolId:s.schoolId,...(req.query.serviceDate?{serviceDate:new Date(String(req.query.serviceDate))}:{})},include:{items:true},orderBy:{serviceDate:"asc",createdAt:"desc"},take:500}));return res.json({data});}));
canteenRouter.get("/students/me/:organizationId/:schoolId/canteen/preorders",wrap(async(req,res)=>{const userId=req.auth!.userId,organizationId=String(req.params.organizationId),schoolId=String(req.params.schoolId);const link=await withPlatformContext(prisma,tx=>tx.studentAccountLink.findFirst({where:{organizationId,schoolId,userId,isActive:true,student:{status:"ACTIVE"}},select:{studentId:true}}));if(!link)return res.status(403).json({error:"Active student account link required"});const data=await withTenantContext(prisma,{organizationId,schoolId,userId},tx=>tx.canteenPreorder.findMany({where:{organizationId,schoolId,studentId:link.studentId},include:{items:true},orderBy:{serviceDate:"desc",createdAt:"desc"},take:50}));return res.json({data});}));
canteenRouter.get("/parents/me/:organizationId/:schoolId/canteen/preorders",wrap(async(req,res)=>{const userId=req.auth!.userId,organizationId=String(req.params.organizationId),schoolId=String(req.params.schoolId);const studentIds=await parentCanteenStudentIds(userId,organizationId,schoolId);if(!studentIds.length)return res.status(403).json({error:"Guardian consent and parent canteen permission required"});const data=await withTenantContext(prisma,{organizationId,schoolId,userId},tx=>tx.canteenPreorder.findMany({where:{organizationId,schoolId,studentId:{in:studentIds}},include:{items:true},orderBy:{serviceDate:"desc",createdAt:"desc"},take:100}));return res.json({data});}));
canteenRouter.post(base+"/preorders/:preorderId/cancel",wrap(async(req,res)=>{const s=await scope(req,res,"canteen.manage");if(!s)return;const p=z.object({reason:z.string().trim().min(1).max(300)}).safeParse(req.body);if(!p.success)return res.status(400).json({error:"Cancellation reason required"});const data=await withTenantContext(prisma,s,async tx=>{const order=await tx.canteenPreorder.findFirst({where:{id:req.params.preorderId,organizationId:s.organizationId,schoolId:s.schoolId}});if(!order)throw Object.assign(new Error("Preorder not found"),{status:404});if(["CANCELLED","COMPLETED"].includes(order.status))throw Object.assign(new Error("Preorder cannot be cancelled"),{status:409});const policy=await tx.canteenPreorderPolicy.findUnique({where:{organizationId_schoolId:{organizationId:s.organizationId,schoolId:s.schoolId}}});if(policy&&!policy.allowCancellation)throw Object.assign(new Error("Cancellation disabled by policy"),{status:409});const cutoff=serviceCutoff(order.serviceDate,policy?.serviceTime||"12:00",policy?.cancellationCutoffMinutes??60);if(new Date()>=cutoff)throw Object.assign(new Error("Cancellation cutoff passed"),{status:409});const paid=order.paymentStatus==="PAID",refundStatus=paid?"REQUESTED":"NOT_REQUIRED";return tx.canteenPreorder.update({where:{id:order.id},data:{status:"CANCELLED",cancelledAt:new Date(),cancellationReason:p.data.reason,refundStatus,refundAmount:paid?order.total:0,refundRequestedAt:paid?new Date():null}});});return res.json({data});}));
canteenRouter.patch(base+"/preorders/:preorderId/refund",wrap(async(req,res)=>{const s=await scope(req,res,"canteen.manage");if(!s)return;const p=z.object({refundStatus:z.enum(["PROCESSING","REFUNDED","FAILED"]),refundReference:z.string().max(120).optional()}).safeParse(req.body);if(!p.success)return res.status(400).json({error:"Invalid refund update"});const data=await withTenantContext(prisma,s,async tx=>{const order=await tx.canteenPreorder.findFirst({where:{id:req.params.preorderId,organizationId:s.organizationId,schoolId:s.schoolId}});if(!order)throw Object.assign(new Error("Preorder not found"),{status:404});if(order.status!=="CANCELLED"||order.refundStatus==="NOT_REQUIRED")throw Object.assign(new Error("Refund is not applicable"),{status:409});if(order.refundStatus==="REFUNDED")throw Object.assign(new Error("Refund already completed"),{status:409});return tx.canteenPreorder.update({where:{id:order.id},data:{refundStatus:p.data.refundStatus,refundReference:p.data.refundReference}});});return res.json({data});}));
// P549 self-service cancellation routes for linked student and consented guardian accounts.
async function selfServiceCancelPreorder(organizationId:string,schoolId:string,userId:string,preorderId:string,studentId:string,reason:string){return withTenantContext(prisma,{organizationId,schoolId,userId},async tx=>{const order=await tx.canteenPreorder.findFirst({where:{id:preorderId,organizationId,schoolId,studentId}});if(!order)throw Object.assign(new Error("Preorder not found for this student"),{status:404});if(order.status!=="PLACED")throw Object.assign(new Error("Only placed preorders can be cancelled"),{status:409});const policy=await tx.canteenPreorderPolicy.findUnique({where:{organizationId_schoolId:{organizationId,schoolId}}});if(policy&&!policy.allowCancellation)throw Object.assign(new Error("Cancellation disabled by school policy"),{status:409});const cutoff=serviceCutoff(order.serviceDate,policy?.serviceTime||"12:00",policy?.cancellationCutoffMinutes??60);if(new Date()>=cutoff)throw Object.assign(new Error("Cancellation cutoff passed"),{status:409});const paid=order.paymentStatus==="PAID";return tx.canteenPreorder.update({where:{id:order.id},data:{status:"CANCELLED",cancelledAt:new Date(),cancellationReason:reason,refundStatus:paid?"REQUESTED":"NOT_REQUIRED",refundAmount:paid?order.total:0,refundRequestedAt:paid?new Date():null}});});}
canteenRouter.post("/students/me/:organizationId/:schoolId/canteen/preorders/:preorderId/cancel",wrap(async(req,res)=>{const userId=req.auth!.userId,organizationId=String(req.params.organizationId),schoolId=String(req.params.schoolId);const p=z.object({reason:z.string().trim().min(1).max(300)}).safeParse(req.body);if(!p.success)return res.status(400).json({error:"Cancellation reason required"});const link=await withPlatformContext(prisma,tx=>tx.studentAccountLink.findFirst({where:{organizationId,schoolId,userId,isActive:true,student:{status:"ACTIVE"}},select:{studentId:true}}));if(!link)return res.status(403).json({error:"Active student account link required"});const data=await selfServiceCancelPreorder(organizationId,schoolId,userId,String(req.params.preorderId),link.studentId,p.data.reason);return res.json({data});}));
canteenRouter.post("/parents/me/:organizationId/:schoolId/canteen/preorders/:preorderId/cancel",wrap(async(req,res)=>{const userId=req.auth!.userId,organizationId=String(req.params.organizationId),schoolId=String(req.params.schoolId);const p=z.object({studentId:z.string().min(1),reason:z.string().trim().min(1).max(300)}).safeParse(req.body);if(!p.success)return res.status(400).json({error:"Student ID and cancellation reason required"});const studentIds=await parentCanteenStudentIds(userId,organizationId,schoolId);if(!studentIds.includes(p.data.studentId))return res.status(403).json({error:"Guardian consent and linked-student permission required"});const data=await selfServiceCancelPreorder(organizationId,schoolId,userId,String(req.params.preorderId),p.data.studentId,p.data.reason);return res.json({data});}));

// P550 wallet, meal entitlement, and reconciliation API foundation.
const p550TopupSchema=z.object({studentId:z.string().min(1),amount:z.number().positive().max(1000000),idempotencyKey:z.string().trim().min(8).max(120),note:z.string().max(300).optional()});
canteenRouter.post(base+"/wallet/topups",wrap(async(req,res)=>{const s=await scope(req,res,"canteen.manage");if(!s)return;const p=p550TopupSchema.safeParse(req.body);if(!p.success)return res.status(400).json({error:"Invalid wallet top-up",details:p.error.flatten()});const result=await withTenantContext(prisma,s,async tx=>{const student=await tx.student.findFirst({where:{id:p.data.studentId,organizationId:s.organizationId,schoolId:s.schoolId,status:"ACTIVE"},select:{id:true}});if(!student)throw Object.assign(new Error("Active student not found"),{status:404});const duplicate=await tx.canteenWalletTransaction.findFirst({where:{organizationId:s.organizationId,schoolId:s.schoolId,idempotencyKey:p.data.idempotencyKey}});if(duplicate){if(duplicate.type!=="TOPUP"||duplicate.studentId!==student.id)throw Object.assign(new Error("Idempotency key already used for a different wallet transaction"),{status:409});return {transaction:duplicate,duplicate:true};}const wallet=await tx.canteenStudentWallet.upsert({where:{organizationId_schoolId_studentId:{organizationId:s.organizationId,schoolId:s.schoolId,studentId:student.id}},create:{organizationId:s.organizationId,schoolId:s.schoolId,studentId:student.id,balance:0},update:{}});const updated=await tx.canteenStudentWallet.update({where:{id:wallet.id},data:{balance:{increment:p.data.amount}}});const entry=await tx.canteenWalletTransaction.create({data:{organizationId:s.organizationId,schoolId:s.schoolId,studentId:student.id,walletId:wallet.id,type:"TOPUP",amount:p.data.amount,balanceAfter:updated.balance,idempotencyKey:p.data.idempotencyKey,note:p.data.note,createdBy:s.userId}});return {transaction:entry,duplicate:false};});return res.status(201).json({data:result});}));
canteenRouter.get("/students/me/:organizationId/:schoolId/canteen/wallet",wrap(async(req,res)=>{const userId=req.auth!.userId,organizationId=String(req.params.organizationId),schoolId=String(req.params.schoolId);const link=await withPlatformContext(prisma,tx=>tx.studentAccountLink.findFirst({where:{organizationId,schoolId,userId,isActive:true,student:{status:"ACTIVE"}},select:{studentId:true}}));if(!link)return res.status(403).json({error:"Active student account link required"});const data=await withTenantContext(prisma,{organizationId,schoolId,userId},tx=>tx.canteenStudentWallet.findUnique({where:{organizationId_schoolId_studentId:{organizationId,schoolId,studentId:link.studentId}},include:{transactions:{orderBy:{createdAt:"desc"},take:50}}}));return res.json({data});}));
canteenRouter.get("/parents/me/:organizationId/:schoolId/canteen/wallets",wrap(async(req,res)=>{const userId=req.auth!.userId,organizationId=String(req.params.organizationId),schoolId=String(req.params.schoolId);const studentIds=await parentCanteenStudentIds(userId,organizationId,schoolId);if(!studentIds.length)return res.status(403).json({error:"Guardian consent and canteen permission required"});const data=await withTenantContext(prisma,{organizationId,schoolId,userId},tx=>tx.canteenStudentWallet.findMany({where:{organizationId,schoolId,studentId:{in:studentIds}},include:{transactions:{orderBy:{createdAt:"desc"},take:20}}}));return res.json({data});}));
canteenRouter.post(base+"/preorders/:preorderId/pay-wallet",wrap(async(req,res)=>{const s=await scope(req,res,"canteen.manage");if(!s)return;const p=z.object({idempotencyKey:z.string().trim().min(8).max(120)}).safeParse(req.body);if(!p.success)return res.status(400).json({error:"Idempotency key required"});const data=await withTenantContext(prisma,s,async tx=>{const order=await tx.canteenPreorder.findFirst({where:{id:req.params.preorderId,organizationId:s.organizationId,schoolId:s.schoolId}});if(!order)throw Object.assign(new Error("Preorder not found"),{status:404});const duplicate=await tx.canteenWalletTransaction.findFirst({where:{organizationId:s.organizationId,schoolId:s.schoolId,idempotencyKey:p.data.idempotencyKey}});if(duplicate){if(duplicate.referenceId!==order.id)throw Object.assign(new Error("Idempotency key already used"),{status:409});return {preorder:order,transaction:duplicate,duplicate:true};}if(order.status!=="PLACED"||order.paymentStatus!=="UNPAID")throw Object.assign(new Error("Preorder is not payable"),{status:409});const wallet=await tx.canteenStudentWallet.findUnique({where:{organizationId_schoolId_studentId:{organizationId:s.organizationId,schoolId:s.schoolId,studentId:order.studentId}}});if(!wallet||!wallet.isActive)throw Object.assign(new Error("Active wallet not found"),{status:404});const debited=await tx.canteenStudentWallet.updateMany({where:{id:wallet.id,balance:{gte:order.total}},data:{balance:{decrement:order.total}}});if(debited.count!==1)throw Object.assign(new Error("Insufficient balance or concurrent wallet update"),{status:409});const fresh=await tx.canteenStudentWallet.findUnique({where:{id:wallet.id}});const entry=await tx.canteenWalletTransaction.create({data:{organizationId:s.organizationId,schoolId:s.schoolId,studentId:order.studentId,walletId:wallet.id,type:"PREORDER_PAYMENT",amount:order.total,balanceAfter:fresh!.balance,referenceType:"PREORDER",referenceId:order.id,idempotencyKey:p.data.idempotencyKey,createdBy:s.userId}});const paid=await tx.canteenPreorder.update({where:{id:order.id},data:{paymentStatus:"PAID"}});return {preorder:paid,transaction:entry,duplicate:false};});return res.json({data});}));
canteenRouter.post(base+"/meal-entitlements",wrap(async(req,res)=>{const s=await scope(req,res,"canteen.manage");if(!s)return;const p=z.object({studentId:z.string().min(1),entitlementName:z.string().trim().min(1).max(100).optional(),totalMeals:z.number().int().positive().max(10000),validFrom:z.string().datetime(),validTo:z.string().datetime().nullable().optional()}).safeParse(req.body);if(!p.success)return res.status(400).json({error:"Invalid meal entitlement",details:p.error.flatten()});const data=await withTenantContext(prisma,s,async tx=>{const student=await tx.student.findFirst({where:{id:p.data.studentId,organizationId:s.organizationId,schoolId:s.schoolId,status:"ACTIVE"},select:{id:true}});if(!student)throw Object.assign(new Error("Active student not found"),{status:404});if(p.data.validTo&&new Date(p.data.validTo)<new Date(p.data.validFrom))throw Object.assign(new Error("Invalid entitlement date range"),{status:400});return tx.canteenMealEntitlement.create({data:{organizationId:s.organizationId,schoolId:s.schoolId,studentId:student.id,entitlementName:p.data.entitlementName,totalMeals:p.data.totalMeals,validFrom:new Date(p.data.validFrom),validTo:p.data.validTo?new Date(p.data.validTo):null,createdBy:s.userId}});});return res.status(201).json({data});}));
canteenRouter.get(base+"/meal-entitlements",wrap(async(req,res)=>{const s=await scope(req,res);if(!s)return;const data=await withTenantContext(prisma,s,tx=>tx.canteenMealEntitlement.findMany({where:{organizationId:s.organizationId,schoolId:s.schoolId,...(req.query.studentId?{studentId:String(req.query.studentId)}:{})},orderBy:{validFrom:"desc"},take:500}));return res.json({data});}));
canteenRouter.post(base+"/meal-entitlements/:entitlementId/consume",wrap(async(req,res)=>{const s=await scope(req,res,"canteen.manage");if(!s)return;const p=z.object({quantity:z.number().int().positive().max(100),referenceId:z.string().max(120).optional()}).safeParse(req.body);if(!p.success)return res.status(400).json({error:"Invalid entitlement consumption",details:p.error.flatten()});const data=await withTenantContext(prisma,s,async tx=>{const entitlement=await tx.canteenMealEntitlement.findFirst({where:{id:req.params.entitlementId,organizationId:s.organizationId,schoolId:s.schoolId,status:"ACTIVE"}});if(!entitlement)throw Object.assign(new Error("Active entitlement not found"),{status:404});const now=new Date();if(now<entitlement.validFrom||(entitlement.validTo&&now>entitlement.validTo))throw Object.assign(new Error("Entitlement is outside validity period"),{status:409});if(entitlement.consumedMeals+p.data.quantity>entitlement.totalMeals)throw Object.assign(new Error("Entitlement exhausted"),{status:409});const changed=await tx.canteenMealEntitlement.updateMany({where:{id:entitlement.id,consumedMeals:entitlement.consumedMeals,status:"ACTIVE"},data:{consumedMeals:{increment:p.data.quantity}}});if(changed.count!==1)throw Object.assign(new Error("Concurrent entitlement update; retry"),{status:409});return tx.canteenMealEntitlement.findUnique({where:{id:entitlement.id}});});return res.json({data});}));
canteenRouter.get(base+"/wallet/reconciliation",wrap(async(req,res)=>{const s=await scope(req,res,"canteen.manage");if(!s)return;const wallets=await withTenantContext(prisma,s,tx=>tx.canteenStudentWallet.findMany({where:{organizationId:s.organizationId,schoolId:s.schoolId},select:{id:true,studentId:true,balance:true}}));const ledger=await withTenantContext(prisma,s,tx=>tx.canteenWalletTransaction.findMany({where:{organizationId:s.organizationId,schoolId:s.schoolId},select:{walletId:true,type:true,amount:true},take:10000}));const summary=wallets.map(w=>{const rows=ledger.filter(t=>t.walletId===w.id);const expected=rows.reduce((sum,t)=>sum+(t.type==="TOPUP"||t.type==="REFUND"||t.type==="ADJUSTMENT"?Number(t.amount):-Number(t.amount)),0);const current=Number(w.balance);return {walletId:w.id,studentId:w.studentId,balance:current,ledgerBalance:expected,variance:current-expected,balanced:Math.abs(current-expected)<0.005};});return res.json({data:{walletCount:summary.length,discrepancies:summary.filter(row=>!row.balanced),summary}});}));
